// Parse the input date string
const birthDate = new Date(query.birthdate);
const today = new Date();

// Calculate the difference in years
let age = today.getFullYear() - birthDate.getFullYear();
const monthDifference = today.getMonth() - birthDate.getMonth();

// Adjust age if birth month/day has not occurred yet this year
if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < birthDate.getDate())) {
  age--;
}

// Return a clean text string for the agent observation
return `Age calculated successfully: ${age} years old.`;

